CREATE TABLE public.gym_subscription_events (id uuid PRIMARY KEY, gym_id uuid NOT NULL REFERENCES public.gyms(id), member_record_id text NOT NULL, event_type text NOT NULL CHECK(event_type IN ('created','renewed')), occurred_at timestamptz NOT NULL DEFAULT now(), occurred_on date NOT NULL, price numeric NOT NULL CHECK(price>=0), plan_name text NOT NULL);
GRANT SELECT ON public.gym_subscription_events TO authenticated;
GRANT ALL ON public.gym_subscription_events TO service_role;
ALTER TABLE public.gym_subscription_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY gym_reporting_read ON public.gym_subscription_events FOR SELECT TO authenticated USING(public.gym_access(gym_id,'Members'));
CREATE FUNCTION public.capture_subscription_reporting() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE zone text; op uuid; BEGIN IF NEW.kind!='members' THEN RETURN NEW; END IF; IF TG_OP='UPDATE' AND NEW.data->>'subscriptionEventId' IS NOT DISTINCT FROM OLD.data->>'subscriptionEventId' THEN RETURN NEW; END IF; IF coalesce(NEW.data->>'subscriptionEventId','')='' THEN RETURN NEW; END IF; op=(NEW.data->>'subscriptionEventId')::uuid; SELECT coalesce(data->'preferences'->>'timeZone','UTC') INTO zone FROM public.gym_records WHERE gym_id=NEW.gym_id AND kind='gym' LIMIT 1; zone=coalesce(zone,'UTC'); IF NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=zone) THEN RAISE EXCEPTION 'Invalid gym time zone'; END IF; INSERT INTO public.gym_subscription_events(id,gym_id,member_record_id,event_type,occurred_on,price,plan_name) VALUES(op,NEW.gym_id,NEW.id,CASE WHEN TG_OP='INSERT' THEN 'created' ELSE 'renewed' END,(now() AT TIME ZONE zone)::date,(NEW.data->>'planPrice')::numeric,NEW.data->>'plan'); RETURN NEW; END $$;
CREATE TRIGGER capture_subscription_reporting AFTER INSERT OR UPDATE ON public.gym_records FOR EACH ROW EXECUTE FUNCTION public.capture_subscription_reporting();
DO $$ DECLARE definition text; old_clause text; new_clause text; BEGIN SELECT pg_get_functiondef(oid) INTO definition FROM pg_proc WHERE proname='save_gym_records' AND pronamespace='public'::regnamespace; old_clause=$old$IF old IS NOT NULL THEN r=r||jsonb_build_object('planPrice',old->'planPrice','createdByName',old->'createdByName'); ELSE$old$; new_clause=$new$IF old IS NOT NULL THEN IF coalesce(r->>'subscriptionEventId','')!='' AND r->>'subscriptionEventId' IS DISTINCT FROM old->>'subscriptionEventId' THEN r=r||jsonb_build_object('planPrice',coalesce((SELECT data->'price' FROM public.gym_records WHERE gym_id=g AND kind='plans' AND data->>'name'=r->>'plan' LIMIT 1),'0'::jsonb),'createdByName',old->'createdByName'); ELSE r=r||jsonb_build_object('planPrice',old->'planPrice','createdByName',old->'createdByName'); END IF; ELSE$new$; IF position(old_clause IN definition)=0 THEN RAISE EXCEPTION 'Expected price preservation clause not found'; END IF; EXECUTE replace(definition,old_clause,new_clause); END $$;
CREATE FUNCTION public.gym_reporting_events(g uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.gym_access(g,'Members') THEN RAISE EXCEPTION 'Gym reporting access required'; END IF; RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'memberId',member_record_id,'date',occurred_on,'price',price,'kind',event_type) ORDER BY occurred_at) FROM public.gym_subscription_events WHERE gym_id=g),'[]'::jsonb); END $$;
REVOKE ALL ON FUNCTION public.gym_reporting_events(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.gym_reporting_events(uuid) TO authenticated, service_role;